import * as core from "@actions/core";
import { publishStatusComment } from "../github/status.js";
import { revalidatePullRequestIdentity } from "../write/pr.js";
import { assertRemoteBranchHead, createGitHubCommitFromWorkspace, updateRemoteBranch, } from "../write/github.js";
import { assertValidationSucceeded, assertWriteValidationConfigured, runValidationCommandsInDocker, } from "../write/validate.js";
import { inspectWorkspaceChanges } from "../write/workspace.js";
export async function finishFix(input) {
    const task = input.result.output.operation === "task";
    const label = task ? "task" : "fix";
    input.onPhase?.("validation");
    await revalidatePullRequestIdentity(input.client, input.target.owner, input.target.repo, input.target.issueNumber, input.identity);
    const changes = await inspectWorkspaceChanges(input.snapshot);
    if (changes.all.length === 0) {
        throw new Error(`DSH reported a ${label} but produced no file changes`);
    }
    assertWriteValidationConfigured(input.inputs.runTests, input.inputs.testCommands);
    const tests = await runValidationCommandsInDocker(input.snapshot.workerRoot, input.inputs.testCommands, input.inputs.containerImage, input.validationTimeoutMs);
    assertValidationSucceeded(tests);
    input.onPhase?.("write");
    await revalidatePullRequestIdentity(input.client, input.target.owner, input.target.repo, input.target.issueNumber, input.identity);
    const created = await createGitHubCommitFromWorkspace(input.client, {
        owner: input.target.owner,
        repo: input.target.repo,
        baseSha: input.boundHeadSha,
        message: task ? "feat: apply DeepSeek Harness task" : "fix: apply DeepSeek Harness fix",
    }, input.snapshot);
    await revalidatePullRequestIdentity(input.client, input.target.owner, input.target.repo, input.target.issueNumber, input.identity);
    await assertRemoteBranchHead(input.client, input.target.owner, input.target.repo, input.headBranch, input.boundHeadSha);
    await updateRemoteBranch(input.client, input.target.owner, input.target.repo, input.headBranch, created.sha);
    try {
        await publishStatusComment(input.client, input.target, input.expectedAuthorId, `DeepSeek Harness ${label} prepared`, `${input.result.output.summary}\n\nConfigured validation passed.\n\nCommit: \`${created.sha}\`\n\nChanged: ${created.paths.map((path) => `\`${path}\``).join(", ")}`, input.runUrl, task ? "task" : "write");
        return { commitSha: created.sha, paths: created.paths, status: "success" };
    }
    catch {
        // The branch update is the authoritative write. A later comment failure
        // must not turn an already-pushed fix into a failed/retried mutation.
        core.warning(`Partial success: ${label} commit ${created.sha} was pushed, but its GitHub status comment could not be published.`);
        try {
            await core.summary
                .addHeading(`DeepSeek Harness ${label}: partial success`, 2)
                .addRaw(`${task ? "Task" : "Fix"} commit \`${created.sha}\` was pushed, but the status comment could not be published.`)
                .write();
        }
        catch {
            core.warning("The partial-success step summary could not be published either.");
        }
        return { commitSha: created.sha, paths: created.paths, status: "partial-success" };
    }
}
